package fable.hideseek.imba.client;import fable.hideseek.imba.config.MessageSettingsConfig;import java.util.HashMap;import java.util.Map;public final class MessageSettingsClientData{private static final Map<String,Boolean> STATE=new HashMap<>();private MessageSettingsClientData(){}public static void replace(Map<String,Boolean> next){STATE.clear();STATE.putAll(next);}public static boolean isEnabled(String key){if(STATE.containsKey(key))return STATE.get(key);for(var entry:MessageSettingsConfig.CATALOG)if(entry.key().equals(key))return entry.defaultEnabled();return true;}public static Map<String,Boolean> snapshot(){return Map.copyOf(STATE);}}
